const D = { energy:.6, density:.5, scale:1, speed:1, hue:104, teeth:.6, lobes:0, x:.5, y:.5, style:'herbarium', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7) * 43758.5453; return s - Math.floor(s); };
const sty = P.style;
const EN = cl(P.energy,0,1), DN = cl(P.density,0,1), SC = cl(P.scale,.35,2.2);
const TH = cl(P.teeth,0,1), NL = Math.round(cl(P.lobes,0,7)), AL = cl(P.alpha,0,100)/100;

// ---- monotonic internal clock (survives t0 resets) -----------------------
if (S.lastT == null || K.t < S.lastT) S.lastT = K.t;
let dt = K.t - S.lastT; S.lastT = K.t;
if (!(dt >= 0) || dt > .25) dt = 1/60;
const SP = cl(P.speed,.05,4);
S.tt = (S.tt || 0) + dt*SP;
const T = S.tt;
const gust = .9*Math.sin(T*.61) + .5*Math.sin(T*1.43+1.7) + .32*Math.sin(T*2.29);
const breeze = (.25 + .9*EN)*gust + A.lowmid*.7 + K.pulse*.18*K.intensity;
const season = cl(((K.section||0)/7)*.55 + .45*(.5+.5*Math.sin(T*.041+.6)), 0, 1);

// ---- style ---------------------------------------------------------------
const H = P.hue;
let papH, papS, papB, inkH, inkS, inkB, dark;
if (sty === 'cyanotype') { papH = (212 + (H-212)*.18 + 360)%360; papS = 84; papB = 26; inkH = papH; inkS = 5; inkB = 97; dark = 1; }
else if (sty === 'xray') { papH = 196; papS = 42; papB = 15; inkH = H; inkS = 45; inkB = 95; dark = 1; }
else if (sty === 'skeleton') { papH = 30; papS = 12; papB = 71; inkH = 24; inkS = 52; inkB = 20; dark = 0; }
else { papH = 40; papS = 16; papB = 67; inkH = 26; inkS = 56; inkB = 17; dark = 0; }

// ---- specimen sheet ground ----------------------------------------------
const bgKey = [width,height,sd,sty,H].join('|');
if (!S.g || S.bgKey !== bgKey) {
  S.bgKey = bgKey;
  const bw = Math.min(620, Math.max(240, width|0));
  const bh = Math.max(1, Math.round(bw*height/Math.max(1,width)));
  const g = (S.g && S.g.width === bw && S.g.height === bh) ? S.g : createGraphics(bw, bh);
  S.g = g; g.colorMode(HSB, 360, 100, 100, 100);
  g.push(); g.noStroke(); g.background(papH, papS, papB);
  if (sty === 'cyanotype') {
    for (let i=0;i<190;i++){ const w2 = bw*(.25+fr(i*2.9)*.95);
      g.fill(papH, papS-fr(i*4.4)*26, papB + (fr(i*6.6)-.44)*19, 25);
      g.rect(fr(i*8.1)*bw-w2*.3, fr(i*5.3)*bh, w2, bh*.014 + fr(i*9.9)*bh*.022); }
  } else if (sty === 'xray') {
    for (let i=0;i<2400;i++){ g.fill(194, 28, 44+fr(i*4.4)*46, 8); g.rect(fr(i*3.9)*bw, fr(i*6.1+3)*bh, 1.3, 1.3); }
  } else {
    for (let i=0;i<2800;i++){ g.fill(papH, papS*(.5+fr(i*2.3)), papB + (fr(i*5.1)-.5)*26, 44);
      g.rect(fr(i*3.1)*bw, fr(i*7.7+9)*bh, 1.4, 1.4); }
    for (let i=0;i<20;i++){ const fx=fr(i*13.3+2)*bw, fy=fr(i*17.1+5)*bh, r=bw*(.015+fr(i*3.7)*.055);
      for (let k=0;k<3;k++){ g.fill(24, 46, 40, 5); g.ellipse(fx, fy, r*(1+k*.7), r*(.85+k*.6)); } }
    g.noFill(); g.stroke(inkH, 30, 40, 16); g.strokeWeight(1);      // sheet rule
    g.rect(bw*.035, bh*.045, bw*.93, bh*.91); g.noStroke();
  }
  const dc = g.drawingContext;
  const rg = dc.createRadialGradient(bw*.5, bh*.5, bw*.12, bw*.5, bh*.5, bw*.82);
  rg.addColorStop(0, 'rgba(0,0,0,0)'); rg.addColorStop(1, 'rgba(0,0,0,0.36)');
  dc.fillStyle = rg; dc.fillRect(0, 0, bw, bh);
  g.pop();
}

// ---- leaf pool: 9 specimens on a jittered 3x3 sheet, staggered life cycles
const NMAX = 9, TG = 3, TE = 27, TM = 47, TS = 64, TF = 71;   // primordium/expand/mature/senesce/fall
const ORD = [4,0,8,2,6,1,7,3,5];        // spread the drawn subset across the sheet
const reseed = l => {
  const j = l.id*29.3 + (l.gen = (l.gen||0)+1)*11.9;
  const c0 = ORD[l.id], cx = c0 % 3, cy = (c0/3)|0;
  l.ox = (cx + .18 + fr(j*1.3)*.64)/3;
  l.oy = (cy + .18 + fr(j*2.1)*.64)/3;
  l.rot = (fr(j*3.7)-.5)*2.6;
  l.sz = .62 + fr(j*4.9)*.62;
  l.hj = (fr(j*5.3)-.5)*30;
  l.nt = 8 + ((fr(j*6.1)*10)|0);        // final tooth count for this specimen
  l.wr = .26 + fr(j*7.3)*.16;           // width ratio
  l.ph = fr(j*8.7)*6.28;
  l.spin = (fr(j*9.3)-.5)*2.2;
  l.age = 0;
};
if (!S.lv || S.lv.length !== NMAX || S.szKey !== width+'x'+height+sd) {
  S.szKey = width+'x'+height+sd; S.lv = [];
  for (let i=0;i<NMAX;i++){ const l = { id:i }; reseed(l); l.age = fr(i*19.7)*TF; S.lv.push(l); }
}
for (let i=0;i<NMAX;i++){ const l = S.lv[i]; l.age += dt*SP*(.55 + .9*EN)*(.65+.7*K.intensity);
  if (l.age > TF) reseed(l); }

// ---- draw ----------------------------------------------------------------
image(S.g, 0, 0, width, height);
const nDraw = Math.max(1, Math.round(2 + DN*7));
const NS = 34, NB = 5;
const wprof = s => Math.pow(cl(s,0,1), .55) * Math.pow(cl(1-s,0,1), .42) / .515;
if (sty === 'xray') blendMode(ADD);
strokeJoin(ROUND); strokeCap(ROUND);

for (let n=0;n<nDraw;n++) {
  const l = S.lv[n]; if (!l) continue;
  const a = l.age;
  const grow = cl((a - TG)/(TE - TG), 0, 1);
  const gr = grow*grow*(3 - 2*grow);                       // smoothstep expansion
  const dry = cl((a - TM)/(TS - TM), 0, 1);
  const fall = a > TS ? cl((a - TS)/(TF - TS), 0, 1) : 0;
  const L = u*.30*SC*l.sz*(.06 + .94*gr);
  const W = L*l.wr;
  const ntNow = Math.max(0, Math.round(l.nt * cl(gr*1.25, 0, 1)));  // teeth inserted as the margin lengthens
  const flut = Math.sin(T*(1.24 + (l.ph%1)*.9) + l.ph)*.5 + Math.sin(T*2.37 + l.ph*1.7)*.22;
  let px = (l.ox + (P.x-.5)*.6)*width, py = (l.oy + (P.y-.5)*.6)*height;
  let rot = l.rot + (breeze*.10 + flut*.13)*(.4 + EN);
  if (fall > 0) { px += breeze*u*.16*fall + u*.10*fall*Math.sin(T*1.31 + l.ph);
    py += u*.9*fall*fall; rot += l.spin*fall*7; }
  const fade = 1 - fall*fall*.55;
  const hj = ((P.hue + l.hj + season*30) % 360 + 360) % 360;

  push(); translate(px, py); rotate(rot); translate(-L*.42, 0);
  if (!dark && fall === 0) {                              // pressed-specimen cast shadow
    noStroke(); fill(inkH, 22, 22, 11*AL);
    beginShape();
    for (let i=0;i<=NS;i++){ const s=i/NS; vertex(L*s + L*.012, wprof(s)*W + L*.02); }
    for (let i=NS;i>=0;i--){ const s=i/NS; vertex(L*s + L*.012, -wprof(s)*W + L*.02); }
    endShape(CLOSE);
  }
  // --- lamina: nested bands = the chlorophyll drain front moving margin -> midrib
  for (let b=0;b<NB;b++) {
    const scb = 1 - b*(.9/NB);
    const bp = b/(NB-1);
    const gold = cl((dry*1.25 - bp*.85)*2.0, 0, 1);
    const brown = cl((dry - .62)*2.6, 0, 1);
    let ch = hj*(1-gold) + 42*gold;
    if (brown > 0) ch = 42*(1-brown) + 24*brown;
    const cs = (52 + b*5 - season*12) + gold*26 - brown*18;
    const cb = (40 + b*7)*(1-gold*.35) + gold*68 - brown*30;
    if (sty === 'cyanotype') { noStroke(); fill(inkH, 3 + b*1.5, 99 - b*7 - dry*16, (dark?86:90)*AL*fade); }
    else if (sty === 'xray') { noStroke(); fill(hj, 40 + b*6, 22 - b*2, (16 - b*1.6)*AL*fade); }
    else if (sty === 'skeleton') { if (b>0) continue; noStroke(); fill(hj, 22, 62 + dry*10, 26*AL*fade); }
    else { noStroke(); fill(((ch%360)+360)%360, cl(cs,0,100), cl(cb,0,100), (b===0?92:80)*AL*fade); }
    beginShape();
    for (let i=0;i<=NS;i++){ const s=i/NS; const sb = .5 + (s-.5)*scb;
      let w = wprof(sb)*W*scb;
      if (NL > 0) w *= 1 - .38*(.5 - .5*Math.cos(sb*NL*6.2832));
      const phs = sb*ntNow, saw = phs - Math.floor(phs);
      w *= 1 + TH*(saw*.62 - .12)*(b===0?1:.45)*cl(gr*1.6,0,1);
      vertex(L*sb, w); }
    for (let i=NS;i>=0;i--){ const s=i/NS; const sb = .5 + (s-.5)*scb;
      let w = wprof(sb)*W*scb;
      if (NL > 0) w *= 1 - .38*(.5 - .5*Math.cos(sb*NL*6.2832));
      const phs = sb*ntNow, saw = phs - Math.floor(phs);
      w *= 1 + TH*(saw*.62 - .12)*(b===0?1:.45)*cl(gr*1.6,0,1);
      vertex(L*sb, -w); }
    endShape(CLOSE);
    if (sty === 'xray' && b > 2) break;
  }
  // --- margin line
  if (sty === 'herbarium' || sty === 'skeleton') {
    noFill(); stroke(inkH, inkS, inkB, (sty==='skeleton'?40:74)*AL*fade); strokeWeight(Math.max(.6, L*.0055));
    beginShape();
    for (let i=0;i<=NS;i++){ const s=i/NS; let w = wprof(s)*W;
      if (NL > 0) w *= 1 - .38*(.5 - .5*Math.cos(s*NL*6.2832));
      const phs = s*ntNow, saw = phs - Math.floor(phs);
      w *= 1 + TH*(saw*.62 - .12)*cl(gr*1.6,0,1); vertex(L*s, w); }
    for (let i=NS;i>=0;i--){ const s=i/NS; let w = wprof(s)*W;
      if (NL > 0) w *= 1 - .38*(.5 - .5*Math.cos(s*NL*6.2832));
      const phs = s*ntNow, saw = phs - Math.floor(phs);
      w *= 1 + TH*(saw*.62 - .12)*cl(gr*1.6,0,1); vertex(L*s, -w); }
    endShape(CLOSE);
  }
  // --- venation: one secondary per tooth, terminating at that tooth's apex
  const vdry = cl((dry - .34)*1.7, 0, 1);
  const vh = ((hj*(1-vdry) + 34*vdry) % 360 + 360) % 360;
  if (sty === 'cyanotype') stroke(inkH, 30, 62, 60*AL*fade);
  else if (sty === 'xray') stroke(vh, 30, 100, 34*AL*fade);
  else if (sty === 'skeleton') stroke(inkH, 40, 24, 82*AL*fade);
  else stroke(vh, 46 - vdry*18, 34 + vdry*22, 68*AL*fade);
  noFill(); strokeWeight(Math.max(.6, L*.009));
  line(0, 0, L*.985, 0);                                   // midrib
  strokeWeight(Math.max(.45, L*.0042));
  const nv = Math.min(ntNow, 10);
  for (let k=0;k<nv;k++){
    const sTip = (k + .88)/Math.max(1,ntNow);
    if (sTip > .97) continue;
    let wt = wprof(sTip)*W;
    if (NL > 0) wt *= 1 - .38*(.5 - .5*Math.cos(sTip*NL*6.2832));
    wt *= 1 + TH*.5*cl(gr*1.6,0,1);
    const sBase = cl(sTip - .17, .02, .95);
    for (let sg=-1; sg<=1; sg+=2) {
      beginShape();
      for (let q=0;q<=4;q++){ const cvv = q/4;
        const sx = L*(sBase + (sTip-sBase)*cvv);
        vertex(sx, sg*wt*cvv*(.55 + .45*cvv)*(1 + .12*Math.sin(cvv*3.1))); }
      endShape();
    }
  }
  // --- petiole
  strokeWeight(Math.max(.7, L*.011));
  stroke(sty==='cyanotype' ? inkH : vh, sty==='cyanotype'?20:40, sty==='cyanotype'?80:(34+vdry*18), 76*AL*fade);
  line(0, 0, -L*.13, 0);
  pop();
}
